; Written by hand, not generated by c64-source: source.ts generate keeps this file.
; Boot part: the bytes of the generated loader (stage 2) that the loading stage needs while
; the sample plays: $2000-$35ff (the sample) and $9000-$93ff (the sample player). boot.asm
; copies them back after the sample. The loader loads at $0801, so address A is at offset
; 2 + A - $0801 of its file. The second piece is the rest of the file from $9000 on.
!cpu 6510
* = $9b00
boot_stash_low
        !binary "fist_v2_loader.prg", $1600, 2 + $2000 - $0801
boot_stash_high
        !binary "fist_v2_loader.prg", , 2 + $9000 - $0801
